CREATE TABLE IF NOT EXISTS gis_geography_crosswalk_matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, artifact_row_id uuid NOT NULL, state_original text, state_normalized text, lga_original text, lga_normalized text, ward_original text, ward_normalized text, normalization_method text NOT NULL, confidence numeric NOT NULL, match_status text NOT NULL DEFAULT 'CANDIDATE_MATCH', source_registry_id uuid, artifact_sha256 text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(candidate_match_id,artifact_row_id));
CREATE INDEX IF NOT EXISTS gis_geography_crosswalk_candidate_idx ON gis_geography_crosswalk_matches(candidate_match_id);